// ── persistence-internal: cache rebuild ────────────────────────────

/// Rebuilds all derived caches after bulk account insertion.
///
/// Must be called after restoring accounts via `set_account_no_checks`.
/// Order matters: environments first, then sysvars, then BPF programs.
#[cfg(feature = "persistence-internal")]
pub fn rebuild_caches(&mut self) -> Result<(), LiteSVMError> {
    self.reserved_account_keys = Self::reserved_account_keys_for_feature_set(&self.feature_set);
    self.set_builtins();
    self.accounts.rebuild_sysvar_cache();
    self.accounts.load_all_existing_programs()?;
    Ok(())
}

/// We should only use this when we know we're not touching any executable or sysvar accounts,
/// or have already handled such cases.
pub(crate) fn add_account_no_checks(&mut self, pubkey: Address, account: AccountSharedData) {
    self.inner.insert(pubkey, account);
}

pub(crate) fn add_account(
    &mut self,
    pubkey: Address,
    account: AccountSharedData,
) -> Result<(), LiteSVMError> {
    if account.executable()
        && pubkey != Address::default()
        && account.owner() != &native_loader::ID
    {
        let loaded_program = self.load_program(&account)?;
        self.programs_cache
            .replenish(pubkey, Arc::new(loaded_program));
    } else {
        self.maybe_handle_sysvar_account(pubkey, &account)?;
    }
    if account.lamports() == 0 {
        self.inner.remove(&pubkey);
    } else {
        self.add_account_no_checks(pubkey, account);
    }
    Ok(())

fn load_program(
    &self,
    program_account: &AccountSharedData,
) -> Result<ProgramCacheEntry, InstructionError> {
    let metrics = &mut LoadProgramMetrics::default();

    let owner = program_account.owner();
    let program_runtime_for_execution = self.environments.get_env_for_execution().clone();
    let slot = self.sysvar_cache.get_clock().map(|c| c.slot).unwrap_or(0);

    if bpf_loader::check_id(owner) || bpf_loader_deprecated::check_id(owner) {
        ProgramCacheEntry::new(
            owner,

                InstructionError::InvalidAccountData
            })
        } else {
            error!("Index out of bounds using loader_v4.");
            Err(InstructionError::InvalidAccountData)
        }
    } else {
        error!("Owner does not match any expected loader.");
        Err(InstructionError::IncorrectProgramId)
    }
}
